questionvariables.text:
/* Randomise eigenvalues: a in {1,2,3,4}, b in {1,2,3,4}, b != a */
a: rand(4) + 1;
b: rand(4) + 1;
b: if b = a then mod(a, 4) + 1 else b;

/* Correct state transition matrix */
ta1: matrix(
  [exp(-a*t),    0,           0        ],
  [0,       exp(-b*t),   t*exp(-b*t)  ],
  [0,            0,       exp(-b*t)   ]
);
